if hashlib.sha256(raw).hexdigest()!='7c32f89b3e8fc02d893d3e259bf65e0953254daee094bf79b3ae7576162bd3f6':raise SystemExit('Payload integrity failure')
length=int.from_bytes(raw[:8],'big');rows=json.loads(raw[8:8+length]);hash_offset=8+length
root=Path.cwd().resolve();ready=[];seen=set()
baseline=prepare_reviewed_base(root);restored=[];row_paths={r[0] for r in rows}
for name,(data,mode) in baseline.items():
 target=root/name
 if any(p.is_symlink() for p in [target,*target.parents]):raise SystemExit('Symlink blocks recovery: '+name)
 if target.exists() and not target.is_file():raise SystemExit('Invalid recovery target: '+name)
 if name not in row_paths and not target.exists():restored.append((target,data,mode))
for name,content,encoding,hash_size,allow_missing,binary_size in rows:
 hashes=raw[hash_offset:hash_offset+hash_size];hash_offset+=hash_size
 if len(hashes)!=hash_size or hash_size%16:raise SystemExit('Invalid review hashes')
 binary=raw[hash_offset:hash_offset+binary_size];hash_offset+=binary_size
 if len(binary)!=binary_size:raise SystemExit('Invalid image payload')
 rel=PurePosixPath(name)
 if name in seen or rel.is_absolute() or '..' in rel.parts or not rel.parts or str(rel)!=name or rel.parts[0] not in ['.gitignore', 'AltSourceKit', 'DomainBackend', 'Feather', 'Feather.xcconfig', 'Feather.xcodeproj', 'Feather.xcworkspace', 'IDeviceKitten', 'Makefile', 'NimbleKit', 'Tools', 'Zsign', 'firebase.json', 'public']:
  raise SystemExit('Invalid update path')
 seen.add(name);target=root/name
 if any(p.is_symlink() for p in [target,*target.parents]):raise SystemExit('Symlink blocks update: '+name)
 if target.exists() and not target.is_file():raise SystemExit('Invalid target: '+name)
 old=target.read_bytes() if target.exists() else baseline.get(name,(None,0))[0]
 if encoding == 'json-localizations':
  if old is None or name != 'Feather/Resources/Localizable.xcstrings':raise SystemExit('Missing reviewed localization catalogue')
  catalogue=json.loads(old)
  original,additions,*retired=content
  catalogue['strings'].update(original)
  for key,*values in additions:
   entry=catalogue['strings'].setdefault(key,{'extractionState':'manual','localizations':{}})
   locations=entry.setdefault('localizations',{})
   for lang,value in zip(('ar','en','ckb'),values):
    if value is not None:locations[lang]={'stringUnit':{'state':'translated','value':value}}
  if retired:
   for key in retired[0]:catalogue['strings'].pop(key,None)
  data=(json.dumps(catalogue,ensure_ascii=False,indent=2,separators=(',', ' : '))+chr(10)).encode()
 elif encoding == 'generated-ipa-manager':
  if name != 'Tools/Delivery/ipa_manager.yml' or content.count('<XSIGN_IPA_ENGINE>') != 1:
   raise SystemExit('Invalid IPA manager payload')
  publisher = next(row[1] for row in rows if row[0] == 'Tools/Delivery/ipa_publisher.py')
  field = base64.b64encode(zlib.compress(publisher.encode(), 9)).decode()
  data = content.replace('<XSIGN_IPA_ENGINE>', field).encode()
 else:
  if encoding not in ['utf-8','base64','binary']:raise SystemExit('Invalid payload encoding')
  data=binary if encoding=='binary' else (base64.b64decode(content,validate=True) if encoding=='base64' else content.encode()) if content is not None else None
 expected=hashlib.sha256(data).digest() if data is not None else None
 current=hashlib.sha256(old).digest() if old is not None else None
 if current==expected:continue
 known=(hashes[i:i+16] for i in range(0,len(hashes),16))
 if not (allow_missing if current is None else current[:16] in known):
  raise SystemExit('Existing source differs; no files were changed: '+name)
 ready.append((target,data))
for target,data,mode in restored:
 target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data);target.chmod(mode)
for target,data in ready:
 if data is None:
  if target.exists():target.unlink()
 else:target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data)
print('Applied',len(ready),'source updates and restored',len(restored),'base files.')
